    if step < 5 or step > 30:
        continue

    has_train = 'train/batch_size' in line
    has_val = 'val-env/' in line

    if has_train:
        metrics = {}
        for k, v in re.findall(r'([\w/\.@]+):(?:np\.float64\()?([-\d.e+]+)\)?', line):
            try:
                metrics[k] = float(v)
            except:
                pass
        train_steps[step] = metrics

    if has_val and step not in val_steps:
        metrics = {}
        for k, v in re.findall(r'([\w/\.@]+):(?:np\.float64\()?([-\d.e+]+)\)?', line):
            try:
                metrics[k] = float(v)
            except:
                pass
        val_steps[step] = metrics

